Ltac z4s_rng :=
  lazymatch goal with
  | |- ?lo <= bv_unsigned (ev ?E ?j) <= ?hi => let H := fresh "H" in kx_range (EVar j) H; exact H
  | |- 0 <= bv_unsigned (ev ?E ?j1) + 256 * bv_unsigned (ev ?E ?j2) < 65536 =>
      let H1 := fresh "H" in let H2 := fresh "H" in kx_range (EVar j1) H1; kx_range (EVar j2) H2; lia
  end.

Definition z4s_J_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x2 gp tp x5 x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x28 x29 x30 : word)
         (SS n DT SBL SBH DBL DBH : Z) (sbuf dbuf : list byte),
    mem_inv asegs mm ->
    bytes_at asegs mm SS sbuf -> Z.of_nat (length sbuf) = n -> bytes_at asegs mm DT dbuf -> Z.of_nat (length dbuf) = 4 ->
    unpoisoned mm SBL SBH -> SBL <= SS -> SS + n <= SBH -> unpoisoned mm DBL DBH -> DBL <= DT -> DT + 4 <= DBH ->
    rng RNG SS n -> rng RNG DT 4 -> rng RNG (shad SBL) (shlen (SBH - SBL + 7)) -> rng RNG (shad DBL) (shlen (DBH - DBL + 7)) ->
    SBL mod 8 = 0 -> DBL mod 8 = 0 ->
    0x60d000 <= SS -> SS + n <= 2^47 -> 0x60d000 <= DT -> DT + 4 <= 2^47 -> 10 <= n < 2^26 ->
    0x60d000 <= SBL -> SBH <= 2^47 -> 0x60d000 <= DBL -> DBH <= 2^47 ->
    (forall (l1 l2 l3 L : Z) (a0 a5 a6 a7 : word),
       0 <= l1 < 65536 -> 0 <= l2 < 65536 -> 0 <= l3 < 65536 -> L = l1 + l2 + l3 + 6 ->
       evtF asegs RNG Q (MS (mkR (Z_to_bv 64 n) x2 gp tp x5 (Z_to_bv 64 DT) x7 x8 x9 a0 (Z_to_bv 64 l1) (Z_to_bv 64 L)
                                 (Z_to_bv 64 l3) (Z_to_bv 64 l2) a5 a6 a7 x18 x19 x20 x21 x22 x23 x24 x25 x26
                                 (Z_to_bv 64 2147450880) x28 x29 x30 (Z_to_bv 64 SS))
                            F (Z_to_bv 64 0x87dfc) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR (Z_to_bv 64 n) x2 gp tp x5 (Z_to_bv 64 DT) x7 x8 x9 x10 x11 x12 x13 x14 x15 x16 x17
                             x18 x19 x20 x21 x22 x23 x24 x25 x26 (Z_to_bv 64 2147450880) x28 x29 x30 (Z_to_bv 64 SS))
                        F (Z_to_bv 64 0x87d20) fc None mm (seg_rom asegs)).

